// Server-side paging: the grid shows one page of getBills; the page number
// and size go back to Appsmith through onPageChange, which re-runs the query.
var EYE = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-7 11-7 11 7 11 7-4 7-11 7S1 12 1 12z"/><circle cx="12" cy="12" r="3"/></svg>';
var DOWN = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>';

function fmtDateTime(v){
  if (!v) return '';
  var d = new Date(v);
  if (isNaN(d)) return String(v);
  function p(n){ return (n < 10 ? '0' : '') + n; }
  return p(d.getMonth() + 1) + '/' + p(d.getDate()) + '/' + d.getFullYear();
}

function actionRenderer(p){
  if (!p.data) return '';
  return '<span class="acts">'
    + '<button class="act" data-act="open" title="View bill">' + EYE + '</button>'
    + '<button class="act" data-act="file" title="Download bill file">' + DOWN + '</button>'
    + '</span>';
}

var COLS = [
  { headerName: 'Vendor', field: 'Vendor', flex: 1.4, minWidth: 140, tooltipField: 'Vendor' },
  { headerName: 'Invoice Date', field: 'Invoice Date', flex: 1, minWidth: 110 },
  { headerName: 'Billing ID', field: 'Billing ID', flex: 1.1, minWidth: 120, tooltipField: 'Billing ID' },
  { headerName: 'Billing Start Date', field: 'Billing Start Date', flex: 1, minWidth: 120 },
  { headerName: 'Billing End Date', field: 'Billing End Date', flex: 1, minWidth: 120 },
  { headerName: 'Current Charges', field: 'Current Charges', flex: 1, minWidth: 120 },
  { headerName: 'Total Amount Due', field: 'Total Amount Due', flex: 1, minWidth: 120 },
  { headerName: 'Pay Amount', field: 'Pay Amount', flex: 1, minWidth: 110 },
  { headerName: 'Marked For Payment', field: 'Marked For Payment', flex: 1.1, minWidth: 130, valueFormatter: function(p){ return fmtDateTime(p.value); } },
  { headerName: 'Action', field: '__act', width: 100, minWidth: 100, sortable: false, resizable: false, cellRenderer: actionRenderer }
];

var gridApi = null;
var lastSig = '';
var lastTotal = null;
var M = {};

function rows(m){ return (m && Array.isArray(m.data)) ? m.data : []; }
function total(m){ var t = Number(m && m.total); return isNaN(t) ? 0 : t; }
function page(m){ return Math.max(1, Number(m && m.page) || 1); }
function size(m){ return Number(m && m.pageSize) || 20; }
function pages(m){ return Math.max(1, Math.ceil(total(m) / size(m))); }

function sig(m){
  var r = rows(m);
  return (m && m.isLoading ? 'L' : '') + r.length + ':' + (r[0] && r[0].bill_id) + ':' + (r[r.length - 1] && r[r.length - 1].bill_id);
}

function goTo(p, s){
  appsmith.updateModel({ page: p, pageSize: s || size(M) });
  appsmith.triggerEvent('onPageChange');
}

function drawPager(){
  var t = total(M), p = page(M), n = pages(M);
  document.getElementById('count').textContent = t.toLocaleString() + ' Records';
  document.getElementById('pageNo').value = p;
  document.getElementById('pageOf').textContent = 'of ' + n.toLocaleString();
  document.getElementById('prev').disabled = p <= 1;
  document.getElementById('next').disabled = p >= n;
  document.getElementById('size').value = String(size(M));
}

function csv(){
  var cols = COLS.filter(function(c){ return c.field !== '__act'; });
  function q(v){ v = v == null ? '' : String(v); return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; }
  var out = [cols.map(function(c){ return q(c.headerName); }).join(',')];
  gridApi.forEachNodeAfterFilterAndSort(function(n){
    out.push(cols.map(function(c){ return q(c.valueFormatter ? c.valueFormatter({ value: n.data[c.field] }) : n.data[c.field]); }).join(','));
  });
  return out.join('\n');
}

function onCellClicked(e){
  var btn = e.event && e.event.target && e.event.target.closest('[data-act]');
  if (!btn || !e.data) return;
  if (btn.getAttribute('data-act') === 'open'){
    appsmith.updateModel({ openBillId: e.data.bill_id });
    appsmith.triggerEvent('onRowOpen');
  } else {
    appsmith.updateModel({ fileBillId: e.data.bill_id });
    appsmith.triggerEvent('onFileDownload');
  }
}

function render(){
  var div = document.getElementById('myGrid');
  div.innerHTML = '';
  gridApi = agGrid.createGrid(div, {
    columnDefs: COLS,
    rowData: rows(M),
    domLayout: 'autoHeight',
    defaultColDef: { resizable: true, sortable: true, minWidth: 90 },
    popupParent: document.body,
    tooltipShowDelay: 400,
    rowClassRules: { 'deleted': function(p){ return !!(p.data && p.data.deleted_at); } },
    overlayNoRowsTemplate: '<span class="empty">No bills found</span>',
    overlayLoadingTemplate: '<span class="empty">Loading bills…</span>',
    onCellClicked: onCellClicked
  });
  if (M.isLoading) gridApi.showLoadingOverlay();
  lastSig = sig(M);
}

function update(m){
  M = m || {};
  drawPager();
  // A new total means the filters or search changed: start again from page 1.
  if (!M.isLoading && M.total != null) {
    var t = total(M);
    if (lastTotal !== null && t !== lastTotal && page(M) > 1) { lastTotal = t; goTo(1); return; }
    lastTotal = t;
  }
  if (!gridApi){ render(); return; }
  var s = sig(M);
  if (s === lastSig) return;
  lastSig = s;
  if (M.isLoading){ gridApi.showLoadingOverlay(); return; }
  gridApi.setGridOption('rowData', rows(M));
  if (!rows(M).length) gridApi.showNoRowsOverlay(); else gridApi.hideOverlay();
  // Filters can shrink the result below the current page; go back to page 1.
  if (!rows(M).length && page(M) > 1 && total(M) > 0) goTo(1);
}

appsmith.onReady(function(){
  document.getElementById('prev').addEventListener('click', function(){ goTo(page(M) - 1); });
  document.getElementById('next').addEventListener('click', function(){ goTo(page(M) + 1); });
  document.getElementById('pageNo').addEventListener('change', function(e){
    var p = Math.min(pages(M), Math.max(1, parseInt(e.target.value, 10) || 1));
    goTo(p);
  });
  document.getElementById('size').addEventListener('change', function(e){ goTo(1, Number(e.target.value)); });
  document.getElementById('dl').addEventListener('click', function(){
    if (!gridApi) return;
    appsmith.updateModel({ csv: csv() });
    appsmith.triggerEvent('onCsvDownload');
  });
  update(appsmith.model);
  appsmith.onModelChange(update);
});

